// Pseudocode: rotate a tenant's envelope key and re-encrypt data
async function rotateTenantKey(tenantId){
  const cmk = await kms.getTenantCMK(tenantId);
  const dataKey = await kms.generateDataKey(cmk);
  await storage.reencryptTenantData(tenantId, dataKey);
  await audit.log(`Rotated key for ${tenantId}`);
}
